import React, { useId, useLayoutEffect, useRef } from "react";

const scrollLocks = new WeakMap();

function lockBodyScroll(body) {
  let lock = scrollLocks.get(body);

  if (!lock) {
    lock = {
      count: 0,
      overflow: body.style.overflow,
      priority: body.style.getPropertyPriority("overflow"),
    };
    scrollLocks.set(body, lock);
  }

  lock.count += 1;
  body.style.overflow = "hidden";

  return () => {
    lock.count -= 1;

    if (lock.count === 0) {
      body.style.setProperty("overflow", lock.overflow, lock.priority);
      scrollLocks.delete(body);
    }
  };
}

function getFocusableElements(dialog) {
  return Array.from(
    dialog.querySelectorAll(
      "a[href], button, input, select, textarea, [tabindex]"
    )
  ).filter(
    (element) =>
      element.tabIndex !== -1 &&
      !element.hasAttribute("disabled") &&
      !element.matches(":disabled") &&
      !(element.localName === "input" && element.type === "hidden")
  );
}

export function Dialog({ open, onClose, title, children }) {
  const titleId = useId();
  const dialogRef = useRef(null);
  const pressedOnBackdrop = useRef(false);

  useLayoutEffect(() => {
    pressedOnBackdrop.current = false;
    if (!open) return;

    const dialog = dialogRef.current;
    const doc = dialog.ownerDocument;
    const previouslyFocused = doc.activeElement;
    const unlockScroll = lockBodyScroll(doc.body);

    const initialTarget =
      dialog.querySelector("[data-autofocus]") ||
      getFocusableElements(dialog)[0] ||
      dialog;

    if (typeof initialTarget.focus === "function") {
      initialTarget.focus();
    }

    // Keep focus inside even if an autofocus target cannot accept focus.
    if (!dialog.contains(doc.activeElement)) {
      dialog.focus();
    }

    return () => {
      pressedOnBackdrop.current = false;
      unlockScroll();

      if (
        previouslyFocused &&
        previouslyFocused !== doc.body &&
        doc.contains(previouslyFocused) &&
        typeof previouslyFocused.focus === "function"
      ) {
        previouslyFocused.focus();
      }
    };
  }, [open]);

  function handleKeyDown(event) {
    if (event.key === "Escape") {
      event.preventDefault();

      if (!event.repeat) {
        onClose();
      }
      return;
    }

    if (event.key !== "Tab") return;

    const dialog = event.currentTarget;
    const focusableElements = getFocusableElements(dialog);

    if (focusableElements.length === 0) {
      event.preventDefault();
      dialog.focus();
      return;
    }

    const first = focusableElements[0];
    const last = focusableElements[focusableElements.length - 1];
    const activeElement = dialog.ownerDocument.activeElement;

    if (
      activeElement === dialog ||
      !focusableElements.includes(activeElement) ||
      (!event.shiftKey && activeElement === last) ||
      (event.shiftKey && activeElement === first)
    ) {
      event.preventDefault();
      (event.shiftKey ? last : first).focus();
    }
  }

  function handleBackdropPress(event) {
    pressedOnBackdrop.current = event.target === event.currentTarget;
  }

  function handleBackdropClick(event) {
    const shouldClose =
      pressedOnBackdrop.current && event.target === event.currentTarget;

    pressedOnBackdrop.current = false;

    if (shouldClose) {
      onClose();
    }
  }

  if (!open) return null;

  return (
    <div
      data-testid="backdrop"
      onPointerDownCapture={handleBackdropPress}
      onMouseDownCapture={handleBackdropPress}
      onPointerCancelCapture={() => {
        pressedOnBackdrop.current = false;
      }}
      onClickCapture={handleBackdropClick}
    >
      <div
        ref={dialogRef}
        role="dialog"
        aria-modal="true"
        aria-labelledby={titleId}
        tabIndex={-1}
        onKeyDownCapture={handleKeyDown}
      >
        <h2 id={titleId}>{title}</h2>
        {children}
      </div>
    </div>
  );
}
